def fix_escaped_url(text):
	# First convert the double backslash to a single backslash
	text = text.replace('\\\\', '\\')

	# Then convert the Unicode escapes to regular characters.
	def replace_unicode_escapes(match):
		try:
			return chr(int(match.group(1), 16))
		except Exception:
			return match.group(0)

	text = re.sub(r'\\u([0-9a-fA-F]{4})', replace_unicode_escapes, text)

	# Further exchanges
	text = text.replace('\\/', '/')
	text = text.replace('"', '')
	return text


def first(currUrl):
	first_page = currUrl
	if not currUrl.endswith('/1') or not currUrl.endswith('/1/'):
		first_page = currUrl + '1/'
	return first_page


