def decodeUrl(text):
	replacements = {'%20': ' ', '%21': '!', '%22': '"', '%23': '&', '%24': '$', '%25': '%', '%26': '&', '%2B': '+', '%2F': '/', '%3A': ':', '%3B': ';', '%3D': '=', '&#x3D;': '=', '%3F': '?', '%40': '@'}
	for key, value in replacements.items():
		text = text.replace(key, value)
	return text


